type deployFlags struct {
	env        string
	plan       bool
	allowDirty bool
	watch      bool
	noWait     bool
	timeout    time.Duration
	deployTargetFlags
}

var deployFlagValues = deployFlags{deployTargetFlags: deployTargetFlags{output: deploy.OutputPlain}}

var deployPinCmd = &cobra.Command{
	Use:   "pin <component> [version]",
