		sourceDir:    sourceDir,
		sourceOrigin: sourceOrigin,
		cacheRoot:    t.TempDir(),
		image:        image,
		reg:          reg,
		registryHost: srv.Host,
	}
	f.stubRegistry(t)
	f.publishImage(t)

	// A fixed clock keeps a manifest reproducible across runs.
	original := now
	now = func() time.Time { return time.Date(2026, 7, 27, 10, 0, 0, 0, time.UTC) }
	t.Cleanup(func() { now = original })

